// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MY_BANK, Log} from "../src/MY_BANK.sol";

uint256 constant VALUE_CAP = 1000000000000000000000000000000;

contract InvMutTest is Test {
    MY_BANK c;

    function setUp() public { c = new MY_BANK(address(new Log())); }

    // Fuzz params:
    // attackerKey: private key for the attacker EOA that will deposit and attempt to Collect
    // depositAmt: amount the attacker will deposit (must be >= MinSum to allow Collect)
    // withdrawAmt: amount attacker requests to Collect
    function testFuzz_property(uint256 attackerKey, uint256 depositAmt, uint256 withdrawAmt) public {
        vm.assume(depositAmt <= VALUE_CAP);
        attackerKey = bound(attackerKey, 1, 115792089237316195423570985008687907852837564279074904382605163141518161494336);
        // Keep values in wide but admissible domain
        address attacker = vm.addr(uint256(attackerKey));
        // Ensure deposit and withdraw are within reasonable bounds and non-zero
        depositAmt = bound(depositAmt, 1 wei, 10 ether);
        withdrawAmt = bound(withdrawAmt, 1 wei, 10 ether);

        // Deploy an attacker helper that will reenter once during Collect's external call
        ReentrantAttacker attackerContract = new ReentrantAttacker(c);

        // Fund EOA and attacker contract
        vm.deal(attacker, depositAmt + 1 ether);
        vm.deal(address(attackerContract), depositAmt + 1 ether);

        // Use the attacker contract as the msg.sender for Put to deposit funds
        // Put expects an address msg.sender that will be the holder; we want the holder to be the attackerContract
        vm.prank(address(attackerContract));
        c.Put{value: depositAmt}(block.timestamp + 1 days);

        // Confirm MinSum requirement: make sure depositAmt >= c.MinSum() so Collect can proceed
        // If depositAmt is too small, attempt to make it large enough by topping up contract balance and calling Put again
        uint256 minSum = c.MinSum();
        if (depositAmt < minSum) {
            uint256 topUp = minSum - depositAmt;
            vm.deal(address(attackerContract), topUp);
            vm.prank(address(attackerContract));
            c.Put{value: topUp}(block.timestamp + 1 days);
            depositAmt = depositAmt + topUp;
        }

        // Now set the attacker helper's target withdraw amount and arrange it to trigger reentry when receiving ETH
        attackerContract.setTargetWithdraw(withdrawAmt);

        // Record pre-state for the holder (the mapping getter returns (unlockTime, balance))
        (uint256 preUnlock, uint256 preBalance) = c.Acc(address(attackerContract));

        // Ensure unlockTime is in the past so Collect's time check can succeed
        // Warp time beyond unlock
        vm.warp(preUnlock + 2 days);

        // Now call Collect from attackerContract externally (so msg.sender == attackerContract)
        // Use try/catch to capture success or revert; some mutants may revert or succeed
        bool ok;
        vm.prank(address(attackerContract));
        try c.Collect{value: 0}(withdrawAmt) {
            ok = true;
        } catch {
            ok = false;
        }

        // Record post-state for the holder
        (uint256 postUnlock, uint256 postBalance) = c.Acc(address(attackerContract));

        // GENERAL RULE (single assertion): For the correct (non-reentrant) contract, if Collect returned success (ok==true)
        // then the holder's recorded balance must have decreased by exactly the amount withdrawn (but not below zero).
        // We assert the contrapositive: if the postBalance is less than preBalance - withdrawAmt then a reentrant over-withdraw occurred.
        // The correct contract should NEVER allow postBalance < preBalance - withdrawAmt after a successful Collect.

        // Only assert when Collect reported success; the mutant will allow reentrant extra drains making postBalance too small.
        if (ok) {
            // Compute expected minimum balance: cannot be less than preBalance - withdrawAmt (saturating at 0)
            uint256 expectedMin = preBalance >= withdrawAmt ? preBalance - withdrawAmt : 0;
            // The reference contract guarantees postBalance >= expectedMin. The mutant removing the require may allow postBalance < expectedMin.
            assertTrue(postBalance >= expectedMin);
        } else {
            // If Collect reverted, we cannot say much; the universal property only constrains successful Collect calls.
            // Still assert that nothing impossible happened: postBalance cannot exceed preBalance (Collect shouldn't increase balance).
            assertTrue(postBalance <= preBalance);
        }
    }
}

// Adversarial helper: reentrant attacker that on receive() will call back into c.Collect exactly once.
contract ReentrantAttacker {
    MY_BANK public target;
    bool private entered;
    uint256 public targetWithdraw;

    constructor(MY_BANK _t) {
        target = _t;
        entered = false;
    }

    function setTargetWithdraw(uint256 _w) public {
        targetWithdraw = _w;
    }

    // receive will be invoked when C sends Ether via call; reenter once to attempt double-withdraw
    receive() external payable {
        if (!entered) {
            entered = true;
            // Attempt to reenter Collect once
            // We ignore success/failure; the behavior difference is observable via c.Acc getter in the test
            try target.Collect{value: 0}(targetWithdraw) {
            } catch {
            }
        }
    }
}
